select * from sys_log


        and user_id = #{dto.userId}


        and (method like concat('%',#{dto.keyword},'%')
         or operation like concat('%',#{dto.keyword},'%')
         or params like concat('%',#{dto.keyword},'%'))


        and create_time >= #{dto.startTime}


        and create_time < #{dto.endTime}
